// Angry Solar System - Physics Toy
let sun;
let planets = [];
let asteroids = [];
let particles = [];
let stars = [];
let isAiming = false;
let aimStart;

function setup() {
  createCanvas(windowWidth || 800, windowHeight || 600);
  aimStart = createVector(0, 0);
  for (let i = 0; i < 80; i++) {
    stars.push({ x: random(width), y: random(height), s: random(1, 3) });
  }
  resetSystem();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  if (sun) {
    sun.pos.set(width / 2, height / 2);
  }
}

function resetSystem() {
  planets = [];
  asteroids = [];
  particles = [];
  sun = {
    pos: createVector(width / 2, height / 2),
    r: 40,
    mass: 500,
    rage: 0.8
  };

  let orbits = [
    { r: 80, speed: 2.2, size: 10, col: [255, 100, 80], mass: 10 },
    { r: 130, speed: 1.7, size: 14, col: [240, 180, 50], mass: 20 },
    { r: 190, speed: 1.4, size: 16, col: [60, 180, 240], mass: 25 },
    { r: 260, speed: 1.1, size: 24, col: [210, 120, 80], mass: 60 },
    { r: 330, speed: 0.9, size: 20, col: [220, 200, 120], mass: 45 }
  ];

  for (let o of orbits) {
    let ang = random(TWO_PI);
    let p = createVector(sun.pos.x + cos(ang) * o.r, sun.pos.y + sin(ang) * o.r);
    let v = createVector(-sin(ang), cos(ang)).mult(o.speed);
    planets.push({
      pos: p,
      vel: v,
      r: o.size,
      mass: o.mass,
      col: o.col,
      anger: random(0.4, 0.9),
      trail: []
    });
  }

  for (let i = 0; i < 25; i++) {
    let ang = random(TWO_PI);
    let distR = random(210, 235);
    let spd = random(1.2, 1.3);
    asteroids.push({
      pos: createVector(sun.pos.x + cos(ang) * distR, sun.pos.y + sin(ang) * distR),
      vel: createVector(-sin(ang), cos(ang)).mult(spd),
      r: random(3, 6),
      mass: 2
    });
  }
}

function draw() {
  background(15, 12, 25);

  // Stars
  stroke(200, 200, 255);
  strokeWeight(1);
  for (let s of stars) {
    point(s.x, s.y);
  }

  // Gravity & Update planets
  for (let i = planets.length - 1; i >= 0; i--) {
    let p = planets[i];
    let dVec = p5.Vector.sub(sun.pos, p.pos);
    let d = constrain(dVec.mag(), 30, 600);
    let force = (sun.mass * 1.5) / (d * d);
    let acc = dVec.normalize().mult(force);
    p.vel.add(acc);
    p.pos.add(p.vel);

    p.trail.push(p.pos.copy());
    if (p.trail.length > 20) p.trail.shift();

    // Trail
    noFill();
    stroke(p.col[0], p.col[1], p.col[2], 100);
    strokeWeight(2);
    beginShape();
    for (let pt of p.trail) {
      vertex(pt.x, pt.y);
    }
    endShape();

    // Draw planet
    noStroke();
    fill(p.col[0], p.col[1], p.col[2]);
    circle(p.pos.x, p.pos.y, p.r * 2);

    // Angry face
    fill(255);
    circle(p.pos.x - p.r * 0.3, p.pos.y - p.r * 0.2, p.r * 0.4);
    circle(p.pos.x + p.r * 0.3, p.pos.y - p.r * 0.2, p.r * 0.4);
    fill(0);
    circle(p.pos.x - p.r * 0.25, p.pos.y - p.r * 0.2, p.r * 0.2);
    circle(p.pos.x + p.r * 0.25, p.pos.y - p.r * 0.2, p.r * 0.2);
    stroke(0);
    strokeWeight(1.5);
    line(p.pos.x - p.r * 0.5, p.pos.y - p.r * 0.4, p.pos.x - p.r * 0.1, p.pos.y - p.r * 0.25);
    line(p.pos.x + p.r * 0.5, p.pos.y - p.r * 0.4, p.pos.x + p.r * 0.1, p.pos.y - p.r * 0.25);
    line(p.pos.x - p.r * 0.3, p.pos.y + p.r * 0.3, p.pos.x + p.r * 0.3, p.pos.y + p.r * 0.25);
  }

  // Asteroids
  for (let a of asteroids) {
    let dVec = p5.Vector.sub(sun.pos, a.pos);
    let d = constrain(dVec.mag(), 25, 500);
    let force = (sun.mass * 1.2) / (d * d);
    a.vel.add(dVec.normalize().mult(force));
    a.pos.add(a.vel);

    noStroke();
    fill(160, 140, 120);
    circle(a.pos.x, a.pos.y, a.r * 2);
  }

  // Sun (Angry Star)
  noStroke();
  fill(255, 140 + sin(frameCount * 0.1) * 30, 0, 50);
  circle(sun.pos.x, sun.pos.y, sun.r * 2.8 + sin(frameCount * 0.2) * 10);
  fill(255, 60, 0, 120);
  circle(sun.pos.x, sun.pos.y, sun.r * 2.3);
  fill(255, 180, 20);
  circle(sun.pos.x, sun.pos.y, sun.r * 2);

  // Sun angry face
  fill(0);
  ellipse(sun.pos.x - 14, sun.pos.y - 8, 10, 14);
  ellipse(sun.pos.x + 14, sun.pos.y - 8, 10, 14);
  fill(255, 50, 0);
  circle(sun.pos.x - 12, sun.pos.y - 8, 4);
  circle(sun.pos.x + 12, sun.pos.y - 8, 4);

  // Angry brows
  stroke(100, 20, 0);
  strokeWeight(4);
  line(sun.pos.x - 24, sun.pos.y - 20, sun.pos.x - 4, sun.pos.y - 12);
  line(sun.pos.x + 24, sun.pos.y - 20, sun.pos.x + 4, sun.pos.y - 12);

  // Gritted teeth
  fill(255);
  stroke(80, 20, 0);
  strokeWeight(2);
  rect(sun.pos.x - 16, sun.pos.y + 10, 32, 12, 4);
  line(sun.pos.x - 16, sun.pos.y + 16, sun.pos.x + 16, sun.pos.y + 16);
  for (let tx = sun.pos.x - 10; tx <= sun.pos.x + 10; tx += 6) {
    line(tx, sun.pos.y + 10, tx, sun.pos.y + 22);
  }

  // Slingshot aim preview
  if (isAiming) {
    stroke(255, 255, 100, 200);
    strokeWeight(2);
    line(aimStart.x, aimStart.y, mouseX, mouseY);
    noStroke();
    fill(255, 100, 100, 180);
    circle(aimStart.x, aimStart.y, 18);
  }

  // UI text
  noStroke();
  fill(255, 220, 180);
  textSize(14);
  textAlign(CENTER);
  text("ANGRY SOLAR SYSTEM - Drag & release to fling angry rogue planets! Press R to reset.", width / 2, 30);
}

function mousePressed() {
  isAiming = true;
  aimStart.set(mouseX, mouseY);
}

function mouseReleased() {
  if (isAiming) {
    let launchVec = p5.Vector.sub(aimStart, createVector(mouseX, mouseY)).mult(0.08);
    let colors = [
      [255, 80, 80],
      [100, 240, 120],
      [255, 160, 50],
      [200, 100, 255]
    ];
    let col = colors[floor(random(colors.length))];
    planets.push({
      pos: aimStart.copy(),
      vel: launchVec,
      r: random(12, 18),
      mass: random(15, 35),
      col: col,
      anger: 1.0,
      trail: []
    });
    isAiming = false;
  }
}

function keyPressed() {
  if (key === 'r' || key === 'R') {
    resetSystem();
  }
}
